          "jobs": {
            "verify": {
              "runs-on": "ubuntu-latest",
              "steps": [
                {
                  "uses": "actions/checkout@v7.0.1"
                },
                {
                  "uses": "actions/setup-python@v7.0.0",
                  "with": {
                    "cache": "pip",
                    "python-version": "3.12"
                  }
                },
                {
                  "uses": "actions/setup-node@v6",
                  "with": {
                    "node-version": "24.15.0"
                  }
                },
                {
                  "name": "Install",
                  "run": "python -m pip install -e \".[dev]\"\n# msdmd native reader runtimes; without them the collector exits 3.\npython -m pip install -r .agents/skills/msdmd/requirements.txt\nnpm ci --ignore-scripts --prefix .agents/skills/msdmd\n"
                },
                {
                  "name": "Test runtime",
                  "run": "python -m pytest -q"
                },
                {
                  "name": "Audit contract graph",
                  "run": "python scripts/check_contracts.py"
                },
                {
                  "name": "Verify ratios",
                  "run": "python .agents/skills/ratios/ratios_check.py --root ptcna --strict"
                },
                {
                  "name": "Verify metadata collection",
                  "run": "PYTHONPATH=.agents/skills python .agents/skills/msdmd/collect.py \\\n  --root . --repo ptcna --snapshot-identity --out /tmp/ptcna_msdmd.ts\ncmp /tmp/ptcna_msdmd.ts ptcna_msdmd.ts\n"
                },
                {
                  "name": "Build and inspect distributions",
                  "run": "python -m build\npython -m twine check dist/*\n"
                },
                {
                  "name": "Smoke-test wheel",
                  "run": "python -m venv /tmp/ptcna-wheel-smoke\n/tmp/ptcna-wheel-smoke/bin/python -m pip install dist/ptcna-*.whl\n/tmp/ptcna-wheel-smoke/bin/python -c \\\n  \"import ptcna; assert ptcna.__version__ == '0.1.1'\"\n"
                }
              ]
            }
          },
          "name": "quality",
          "on": {
            "pull_request": null,
            "push": {
              "branches": [
                "main"
              ]
            }
          },
